// CR_SECTION(s): the section of a data object, so the compiler picks the original data model whatever its
// size (small data = sda21, large = lis/addi); __declspec only when a draft is compiled (-DCR_DRAFT_CC),
// nothing for m2c's context (tools/draft_batch.py data_decls)
#ifdef CR_DRAFT_CC
#undef __declspec
#define CR_SECTION(s) __declspec(section s)
#else
#define CR_SECTION(s)
#endif

